from fastapi.responses import HTMLResponse

DASHBOARD_HTML = '<!DOCTYPE html>\n<html lang="pt-BR">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Vila Aurora | Centro de Monitoramento</title>\n<style>\n:root{font-family:Arial,sans-serif;color:#172033;background:#f3f5f8}\n*{box-sizing:border-box}\nbody{margin:0}\nheader{background:#142b45;color:white;padding:22px 5%;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px}\nmain{max-width:1200px;margin:28px auto;padding:0 20px}\nh1{font-size:22px;margin:0}\nh2{font-size:18px}\n.panel,.metric{background:white;border:1px solid #dce2e9;border-radius:10px;padding:20px;margin-bottom:18px}\n.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}\n.metric strong{display:block;font-size:28px;margin-top:10px;color:#174d79}\nlabel{display:block;font-weight:bold;margin:12px 0 6px}\ninput{width:100%;padding:12px;border:1px solid #8996a5;border-radius:6px;font-size:16px}\nbutton{padding:11px 18px;border:0;border-radius:6px;background:#145b91;color:white;font-size:15px;cursor:pointer;margin-top:14px}\nbutton:focus,input:focus{outline:3px solid #f0b429;outline-offset:2px}\nbutton.secondary{background:#46566a}\ntable{width:100%;border-collapse:collapse}\nth,td{text-align:left;padding:12px;border-bottom:1px solid #e0e5eb}\nth{background:#edf2f7}\npre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f6f8;padding:14px;border-radius:6px}\n.hidden{display:none}\n.status{font-weight:bold}\n.error{color:#a32121}\n.success{color:#176b39}\n@media(max-width:600px){header{align-items:flex-start}main{padding:0 12px}.panel{overflow-x:auto}}\n</style>\n</head>\n<body>\n<header>\n  <div>\n    <h1>Rede Comunitária Vila Aurora</h1>\n    <div>Centro de monitoramento e supervisão</div>\n  </div>\n  <button id="logout" class="secondary hidden" type="button">Encerrar sessão</button>\n</header>\n<main>\n<section id="login" class="panel">\n  <h2>Acesso ao sistema</h2>\n  <p>Entre com suas credenciais e o código de autenticação.</p>\n  <form id="loginForm">\n    <label for="username">Usuário</label>\n    <input id="username" autocomplete="username" required maxlength="64">\n    <label for="password">Senha</label>\n    <input id="password" type="password" autocomplete="current-password" required>\n    <label for="totp">Código MFA (6 dígitos)</label>\n    <input id="totp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required>\n    <button type="submit">Entrar</button>\n  </form>\n  <p id="loginMessage" role="alert"></p>\n</section>\n\n<section id="dashboard" class="hidden">\n  <div class="panel">\n    <h2>Visão geral</h2>\n    <p id="lastUpdate" aria-live="polite">Aguardando atualização.</p>\n    <button id="refresh" type="button">Atualizar dados</button>\n  </div>\n  <div class="metrics" aria-label="Indicadores da rede">\n    <div class="metric">Espaços monitorados<strong id="spaces">?</strong></div>\n    <div class="metric">Dispositivos<strong id="devices">?</strong></div>\n    <div class="metric">Leituras recebidas<strong id="readings">?</strong></div>\n    <div class="metric">Alertas abertos<strong id="alerts">?</strong></div>\n  </div>\n  <section class="panel">\n    <h2>Estado dos espaços</h2>\n    <div id="spacesData" role="region" aria-label="Dados dos espaços" tabindex="0">\n      <pre>Carregando...</pre>\n    </div>\n  </section>\n  <section class="panel">\n    <h2>Dados operacionais</h2>\n    <pre id="details">Aguardando consulta.</pre>\n  </section>\n  <p id="dataMessage" role="status"></p>\n</section>\n</main>\n<script>\nconst $ = id => document.getElementById(id);\nlet token = sessionStorage.getItem("vila_token");\n\nfunction showDashboard(){\n  $("login").classList.add("hidden");\n  $("dashboard").classList.remove("hidden");\n  $("logout").classList.remove("hidden");\n  refreshData();\n}\nfunction logout(){\n  sessionStorage.removeItem("vila_token");\n  token = null;\n  $("dashboard").classList.add("hidden");\n  $("logout").classList.add("hidden");\n  $("login").classList.remove("hidden");\n}\nasync function api(path){\n  const response = await fetch(path,{headers:{Authorization:"Bearer "+token}});\n  if(response.status === 401 || response.status === 403){\n    logout();\n    throw new Error("Sessão inválida ou sem autorização. Entre novamente.");\n  }\n  if(!response.ok) throw new Error("Falha na consulta: HTTP "+response.status);\n  return response.json();\n}\nfunction findNumber(obj, keys){\n  for(const key of keys){\n    if(obj && typeof obj[key] === "number") return obj[key];\n  }\n  return null;\n}\nasync function refreshData(){\n  $("dataMessage").textContent = "Consultando API central...";\n  try{\n    const status = await api("/api/status");\n    const spaces = await api("/api/spaces");\n    const alerts = await api("/api/alerts");\n    const spaceList = Array.isArray(spaces) ? spaces : (Array.isArray(spaces.items) ? spaces.items : (Array.isArray(spaces.spaces) ? spaces.spaces : []));\n    const alertList = Array.isArray(alerts) ? alerts : (alerts.items || alerts.alerts || []);\n    $("spaces").textContent = spaceList.length || findNumber(status,["spaces_count"]) || "?";\n    $("devices").textContent = findNumber(status,["devices","device_count","total_devices"]) ?? "?";\n    $("readings").textContent = findNumber(status,["telemetry_readings","readings","total_readings"]) ?? "?";\n    $("alerts").textContent = alertList.filter(a => a.resolved === 0 || a.resolved === false).length;\n    $("spacesData").innerHTML = "";\n    const table = document.createElement("table");\n    const head = document.createElement("tr");\n    ["Espaço","Identificação","Dispositivos","Leituras"].forEach(label=>{\n      const th=document.createElement("th"); th.textContent=label; head.appendChild(th);\n    });\n    table.appendChild(head);\n    const summaryList = Array.isArray(status.spaces_summary) ? status.spaces_summary : [];\n    const rows = spaceList.map(item => ({...item, ...(summaryList.find(x => x.id === item.id) || {})}));\n    for(const item of rows){\n      const tr=document.createElement("tr");\n      [item.name || item.id || "?",item.id || "?",item.devices ?? "?",item.telemetry_readings ?? "?"].forEach(value=>{\n        const td=document.createElement("td"); td.textContent=String(value); tr.appendChild(td);\n      });\n      table.appendChild(tr);\n    }\n    $("spacesData").appendChild(table);\n    $("details").textContent=JSON.stringify({status,alerts},null,2);\n    $("lastUpdate").textContent="Última atualização: "+new Date().toLocaleString("pt-BR");\n    $("dataMessage").textContent="Dados atualizados.";\n  }catch(error){\n    $("dataMessage").textContent=error.message+" | "+(error.stack||"sem stack");\n    $("dataMessage").className="error";\n  }\n}\n$("loginForm").addEventListener("submit",async event=>{\n  event.preventDefault();\n  $("loginMessage").textContent="Autenticando...";\n  try{\n    const response=await fetch("/api/auth/login",{\n      method:"POST",\n      headers:{"Content-Type":"application/json"},\n      body:JSON.stringify({\n        username:$("username").value,\n        password:$("password").value,\n        totp_code:$("totp").value\n      })\n    });\n    const result=await response.json();\n    if(!response.ok) throw new Error(result.detail || "Credenciais inválidas.");\n    token=result.access_token;\n    sessionStorage.setItem("vila_token",token);\n    $("password").value="";\n    $("totp").value="";\n    $("loginMessage").textContent="";\n    showDashboard();\n  }catch(error){\n    $("loginMessage").textContent=error.message;\n    $("loginMessage").className="error";\n  }\n});\n$("logout").addEventListener("click",logout);\n$("refresh").addEventListener("click",refreshData);\nif(token) showDashboard();\n</script>\n</body>\n</html>'

def dashboard_response():
    return HTMLResponse(DASHBOARD_HTML)
